#include <stdio.h>
struct St { char name[8]; int marks; };
int main(void) {
    struct St s[4] = {{"Asha", 72}, {"Bina", 65}, {"Chet", 72}, {"Dev", 90}};
    for (int i = 1; i < 4; i++) {           /* insertion sort, descending */
        struct St key = s[i];
        int j = i - 1;
        while (j >= 0 && s[j].marks < key.marks) { s[j + 1] = s[j]; j--; }
        s[j + 1] = key;
    }
    for (int i = 0; i < 4; i++) printf("%s %d\n", s[i].name, s[i].marks);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
struct Node { int d; struct Node *next; };
int main(void) {
    struct Node *head = NULL, **tail = &head;
    for (int i = 1; i <= 3; i++) {                /* append at the end */
        struct Node *n = malloc(sizeof *n);
        n->d = i * 10; n->next = NULL;
        *tail = n; tail = &n->next;
    }
    for (struct Node *p = head; p; p = p->next) printf("%d ", p->d);
    while (head) { struct Node *t = head->next; free(head); head = t; }
    printf("\n%s\n", head == NULL ? "freed" : "leak");
    return 0;
}

