Assume every allocation succeeds. What is the output of the following program?

#include <stdio.h>
#include <stdlib.h>
struct Node { int d; struct Node *next; };
void ins(struct Node **h, int v) {
    while (*h && (*h)->d < v) h = &(*h)->next;
    struct Node *n = malloc(sizeof *n);
    n->d = v; n->next = *h; *h = n;
}
int main(void) {
    struct Node *head = NULL;
    int a[] = {5, 2, 8, 3};
    for (int i = 0; i < 4; i++) ins(&head, a[i]);
    for (struct Node *p = head; p; p = p->next) printf("%d", p->d);
    return 0;
}

